/**
 * CreativeBrief - Structured summary of what the ad should achieve
 *
 * Generated by AI (Gemini) from the normalized request and product context.
 * This brief guides all downstream creative decisions.
 */
export interface CreativeBrief {
  /** Product name */
  productName: string;

  /** Product category */
  productCategory?: string;

  /** Main value proposition or offer */
  offer: string;

  /** Target audience description */
  audience: string;

  /** Pain points the product addresses */
  painPoints: string[];

  /** Key benefits to highlight */
  keyBenefits: string[];

  /** Desired tone for the ad */
  tone: 'direct' | 'professional' | 'casual' | 'enthusiastic';

  /** Call-to-action text */
  cta: string;

  /** Visual style direction */
  visualStyle: 'dynamic' | 'minimalist' | 'bold' | 'cinematic';

  /** The ONE key message viewers should remember */
  keyMessage: string;

  /** Platform-specific constraints */
  targetPlatform: 'tiktok' | 'instagram_reels' | 'youtube_shorts';

  /** Target video duration in seconds */
  targetDuration: number;

  /** Target aspect ratio */
  targetAspectRatio: '9:16' | '16:9' | '1:1';

  /** Language for the ad */
  language: string;

  /** Timestamp when brief was created */
  createdAt: Date;
}
